'use strict';

// MODULES //

var objectKeys = require( '@stdlib/utils/keys' );
var format = require( '@stdlib/string/format' );
var defaults = require( './../defaults.js' );


// VARIABLES //

var RENDERERS = [ 'svg', 'canvas' ];


// MAIN //

/**
* Adds a "general" menu to an editor.
*
* @private
* @param {Editor} editor - editor instance
* @param {Object} conf - editor configuration
* @returns {(Object|null)} menu tree
*/
function addMenu( editor, conf ) {
	var controllers;
	var controller;
	var folder;
	var keys;
	var def;
	var k;
	var i;

	keys = objectKeys( conf );
	if ( keys.length === 0 ) {
		return null;
	}
	folder = editor.addFolder( 'General' );
	folder.close();

	controllers = {};
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		if ( k === 'renderer' ) {
			controller = folder.add( conf, k, RENDERERS );
		} else if ( k === 'background' ) {
			controller = folder.addColor( conf, k );
		} else if ( k === 'description' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'width' || k === 'height' ) {
			def = defaults[ k ];
			controller = folder.add( conf, k ).min( def.min ).step( def.step );
			controller.name( format( '%s (%s)', k, def.units ) );
		} else {
			console.log( 'Unrecognized property in editor configuration. Key: %s.', k );
			continue;
		}
		controllers[ k ] = controller;
	}
	return {
		'folder': folder,
		'controllers': controllers
	};
}


// EXPORTS //

module.exports = addMenu;
